        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt", Steps = "1. Halve and pit avocados, scoop into a bowl.\n2. Mash with a fork to desired consistency.\n3. Stir in diced onion, jalapeño, tomato, and cilantro.\n4. Add lime juice and salt to taste.\n5. Serve immediately with tortilla chips.", AverageRating = 4.6, RatingCount = 21 },
        new Recipe { Id = 7, Title = "Tom Yum Soup", Category = "Thai", Ingredients = "Shrimp\nLemongrass\nGalangal\nKaffir lime leaves\nChili paste\nFish sauce\nLime juice\nMushrooms\nCilantro", Steps = "1. Bring water to a boil with lemongrass, galangal, and lime leaves.\n2. Add mushrooms and chili paste.\n3. Add shrimp and cook until pink.\n4. Season with fish sauce and lime juice.\n5. Garnish with cilantro and serve hot.", AverageRating = 4.4, RatingCount = 7 },
        new Recipe { Id = 8, Title = "Palak Paneer", Category = "Indian", Ingredients = "Paneer\nSpinach\nOnion\nGarlic\nGinger\nGreen chilies\nCumin\nGaram masala\nCream", Steps = "1. Blanch spinach and blend into a puree.\n2. Cube paneer and lightly fry until golden.\n3. Sauté onion, garlic, ginger, and green chilies.\n4. Add cumin and garam masala.\n5. Stir in spinach puree and simmer 10 minutes.\n6. Add paneer cubes and cream.\n7. Serve with roti or rice.", AverageRating = 4.5, RatingCount = 11 },
    };

    private readonly Dictionary<int, List<int>> _ratings = new();

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipe(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);

        var allRatings = _ratings[recipeId];
        recipe.RatingCount = allRatings.Count;
        recipe.AverageRating = Math.Round(allRatings.Average(), 1);
    }

    public void AddRecipe(string title, string category, string ingredients, string steps)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
